// =====================================
// COMMON TOTAL FUNCTION
// =====================================
function get_total_payment_amount(frm) {

    let total = 0;

    // ---------------------------------
    // CALCULATE FROM TESTS TABLE
    // ---------------------------------
    (frm.doc.tests || []).forEach(function(row) {

        total += parseFloat(row.rate || 0);

    });

    // ---------------------------------
    // CONSULTANCY ONLY
    // MULTIPLY BY NUMBER OF SAMPLES
    // ---------------------------------
    if (frm.doc.client_type === "Consultancy") {

        let sample_count = parseFloat(
            frm.doc.number_of_samples || 1
        );

        total = total * sample_count;
    }

    return total;
}


// =====================================
// SOIL SAMPLE COLLECTION
// =====================================
frappe.ui.form.on('Soil Sample Collection', {

    refresh: async function(frm) {

        if (frm.is_new()) return;

        // Always clear any existing alert first
        frm.dashboard.clear_headline();

        if (frm.doc.client_type === "Department") {

            frm.dashboard.set_headline_alert(
                __('Department Samples - Payment Not Required'),
                'blue'
            );

            return;
        }

        let payments = await frappe.db.get_list(
            'Soil Sample Payment',
            {
                filters: { soil_sample_id: frm.doc.name },
                fields: ['name', 'paid'],
                limit: 1
            }
        );

        frm.dashboard.clear_headline();
        // -----------------------------------------
        // PAYMENT EXISTS
        // -----------------------------------------
        if (payments.length > 0) {

            let payment = payments[0];

            // -------------------------------------
            // PAYMENT COMPLETED
            // -------------------------------------
            if (payment.paid) {

                frm.dashboard.set_headline_alert(
                    __('Payment Completed'),
                    'green'
                );

                frm.add_custom_button(
                    __('View Payment'),
                    function() {

                        frappe.set_route(
                            'Form',
                            'Soil Sample Payment',
                            payment.name
                        );

                    }

                ).addClass('btn-success');
            }

            // -------------------------------------
            // PAYMENT PENDING
            // -------------------------------------
            else {

                frm.dashboard.set_headline_alert(
                    __('Payment Pending'),
                    'red'
                );

                frm.add_custom_button(
                    __('Complete Payment'),
                    function() {

                        frappe.set_route(
                            'Form',
                            'Soil Sample Payment',
                            payment.name
                        );

                    }

                ).addClass('btn-danger');
            }
        }

        // -----------------------------------------
        // NO PAYMENT EXISTS
        // -----------------------------------------
        else {

            frm.dashboard.set_headline_alert(
                __('No Payment Created'),
                'orange'
            );

            frm.add_custom_button(
                __('Make Payment'),
                function() {

                    // ✅ COMMON FUNCTION
                    let total =
                        get_total_payment_amount(frm);

                    // ---------------------------------
                    // PASS VALUES
                    // ---------------------------------
                    frappe.route_options = {

                        soil_sample_id:
                            frm.doc.name,

                        total_amount:
                            total,

                        net_payable_amount:
                            total

                    };

                    frappe.new_doc(
                        'Soil Sample Payment'
                    );

                }

            ).addClass('btn-primary');
        }
    }
});

