                                },

                                // ✅ CREATE NEW ANYWAY
                                function() {
                                    create_new_test(frm);
                                }
                            );

                        } else {
                            // ✅ No duplicate → create directly
                            create_new_test(frm);
                        }

                    }
                });

            }, __("Actions"));
        }
    }
});


