function create_new_test(frm) {

    frappe.new_doc('Soil Test Result', {}, (doc) => {

        // 🔹 Main fields
        doc.sample_id = frm.doc.name;
        doc.client_type = frm.doc.client_type;
        doc.type_of_collection = frm.doc.type_of_collection;
        doc.name_of_type = frm.doc.name_of_type;
        doc.number_of_sample = frm.doc.number_of_samples;
        doc.lab_code_prefix = frm.doc.lab_code_prefix;
        doc.lab_code_start = frm.doc.lab_code_start;

        // 🔥 COPY CHILD TABLE
        doc.test_sample_data = [];

        (frm.doc.register_sample_data || []).forEach(row => {

            doc.test_sample_data.push({
                sample_id: row.sample_id,
                values_json: row.values_json,
                lab_code : row.lab_code
            });

        });

    });
}

