// =====================================
// 🔹 RENDER TABLE
// =====================================
async function render_table(frm) {

    try {

        // =====================================
        // ✅ ONLY FOR NON CONSULTANCY
        // =====================================

        if (
            !frm.doc.name_of_type &&
            frm.doc.client_type == "Department"
        ) {

            frm.fields_dict.html.$wrapper.html(`
                <div style="padding:20px;font-weight:600;">
                    Select Scheme or Programs

                </div>
            `);

            return;
        }



        // =====================================
        // 🔹 GET TESTS
        // =====================================

        let final_tests = [];



        // =====================================
        // ✅ CONSULTANCY AUTO TESTS
        // =====================================

        if (
            frm.doc.client_type == "Consultancy" ||
            frm.doc.client_type == "Farmer"
        ) {

            (frm.doc.test_sample_data || []).forEach(row => {

                try {

                    let obj = JSON.parse(
                        row.values_json || "{}"
                    );

                    Object.keys(obj).forEach(key => {

                        if (!final_tests.includes(key)) {
                            final_tests.push(key);
                        }

                    });

                } catch (e) {}

            });

        } else {

            let type_doc = await frappe.db.get_doc(
                "Scheme or Programs",
                frm.doc.name_of_type
            );

            for (let t of type_doc.test_list || []) {

                try {

                    let pkg = await frappe.db.get_doc(
                        "Soil Test Package",
                        t.test_item
                    );

                    if (
                        pkg.included_tests &&
                        pkg.included_tests.length > 1
                    ) {

                        pkg.included_tests.forEach(row => {

                            if (row.linked_package) {

                                final_tests.push(
                                    row.linked_package
                                );
                            }
                        });

                    } else if (
                        pkg.included_tests &&
                        pkg.included_tests.length === 1
                    ) {

                        final_tests.push(
                            pkg.included_tests[0].linked_package
                        );

                    } else {

                        final_tests.push(t.test_item);

                    }

                } catch (e) {

                    final_tests.push(t.test_item);

                }
            }
        }



        final_tests = [...new Set(final_tests)];



        // =====================================
        // 🔹 SAMPLE DATA
        // =====================================

        let data = {};
        let lab_code_map = {};
        let reference_name_map = {};
        let depth_map = {};

        // =====================================
        // ✅ PROFILE SAMPLE CHECK
        // =====================================

        const has_profile_samples =
            frm.doc.client_type === "Department" &&
            (frm.doc.test_sample_data || []).some(row =>
                /\(\d+\/\d+\)$/.test(row.sample_id || "")
            );

        (frm.doc.test_sample_data || []).forEach(row => {

            let sample =
                row.sample_id ||
                row.lab_code ||
                row.name;

            if (!sample) return;

            try {

                data[sample] = JSON.parse(
                    row.values_json || "{}"
                );

            } catch (e) {

                data[sample] = {};

            }

            lab_code_map[sample] =
                row.lab_code ||
                row.sample_id ||
                sample;

            // =====================================
            // ✅ DEPTH
            // =====================================

            depth_map[sample] =
                row.depth || "";

            // =====================================
            // CONSULTANCY ONLY
            // =====================================

            if (frm.doc.client_type === "Consultancy") {

                reference_name_map[sample] =
                    row.reference_name || "";
            }

        });



        // =====================================
        // 🔹 NO DATA
        // =====================================

        if (Object.keys(data).length === 0) {

            frm.fields_dict.html.$wrapper.html(`
                <div style="
                    padding:20px;
                    font-weight:600;
                    color:#777;
                ">
                    No Sample Data Available
                </div>
            `);

            return;
        }



        // =====================================
        // 🔹 HTML TABLE
        // =====================================

        let html = `
        <style>

        .table-container {
            width: 100%;
            overflow-x: auto;
            cursor: grab;
        }

        .custom-table {
            width: max-content;
            min-width: 100%;
            border-collapse: collapse;
        }

        .custom-table th,
        .custom-table td {
            text-align: center;
            padding: 6px;
            white-space: nowrap;
            border: 1px solid #ddd;
        }

        .custom-table th {
            background: #f5f5f5;
            font-weight: 600;
            position: sticky;
            top: 0;
            z-index: 10;
        }

        .custom-table input {
            width: 100%;
            min-width: 80px;
            text-align: center;
        }

        .custom-table input[readonly] {
            background: #f8f9fa;
            border: none;
            pointer-events: none;
            cursor: default;
        }

        </style>

        <div class="table-container">

        <table class="table table-bordered custom-table">

        <thead>

        <tr>
        `;


        // =====================================
        // ✅ SAMPLE ID ONLY FOR DEPARTMENT
        // =====================================

        if (frm.doc.client_type != "Consultancy") {

            html += `
            <th style="min-width:220px;">
                Sample ID
            </th>`;
        }

        // =====================================
        // DEPTH - PROFILE SAMPLES ONLY
        // =====================================

        if (has_profile_samples) {

            html += `
            <th style="min-width:120px;">
                Depth
            </th>`;
        }



        // =====================================
        // ✅ LAB CODE COLUMN
        // =====================================

        html += `
        <th style="min-width:180px;">
            Lab Code
        </th>`;

        // =====================================
        // REFERENCE NAME - CONSULTANCY ONLY
        // =====================================

        if (frm.doc.client_type === "Consultancy") {

            html += `
            <th style="min-width:180px;">
                Reference Name
            </th>`;
        }



        // =====================================
        // ✅ TEST COLUMNS
        // =====================================

        final_tests.forEach(t => {

            html += `
            <th style="min-width:120px;">
                ${t}
            </th>`;

        });


        html += `
        </tr>
        </thead>

        <tbody>
        `;




        // =====================================
        // ✅ TABLE ROWS
        // =====================================

        Object.keys(data).forEach(sample => {

            let lab_code =
                lab_code_map[sample] || "";

            html += `<tr>`;


            // =====================================
            // ✅ SAMPLE ID ONLY FOR DEPARTMENT
            // =====================================

            if (frm.doc.client_type != "Consultancy") {

                html += `
                <td style="min-width:220px;">
                    ${sample}
                </td>`;
            }

            // =====================================
            // DEPTH VALUE - PROFILE SAMPLES ONLY
            // =====================================

            if (has_profile_samples) {

                html += `
                <td style="min-width:120px;">
                    ${depth_map[sample] || "-"}
                </td>`;
            }



            // =====================================
            // ✅ LAB CODE
            // =====================================

            html += `
            <td style="min-width:180px;">
                ${lab_code}
            </td>`;


            // =====================================
            // REFERENCE NAME - CONSULTANCY ONLY
            // =====================================

            if (frm.doc.client_type === "Consultancy") {

                let reference_name =
                    reference_name_map[sample] || "";

                html += `
                <td style="min-width:180px;">
                    ${reference_name}
                </td>`;
            }

            // =====================================
            // ✅ TEST VALUES
            // =====================================

            final_tests.forEach(t => {

                let value =
                    data[sample]?.[t] || "";

                html += `
                <td style="min-width:120px;">

                    ${value || "-"}
                </td>`;


            });

            html += `</tr>`;
        });


        html += `
        </tbody>
        </table>
        </div>
        `;


        frm.fields_dict.html.$wrapper.html(html);



        // =====================================
        // 🔹 DRAG SCROLL
        // =====================================

        let container =
            frm.fields_dict.html.$wrapper.find(
                '.table-container'
            );

        let isDown = false;
        let startX;
        let scrollLeft;

        container.off(
            'mousedown mouseleave mouseup mousemove'
        );

        container.on('mousedown', function(e) {

            isDown = true;

            container.css(
                'cursor',
                'grabbing'
            );

            startX =
                e.pageX -
                container.offset().left;

            scrollLeft =
                container.scrollLeft();

        });


        container.on(
            'mouseleave mouseup',
            function() {

                isDown = false;

                container.css(
                    'cursor',
                    'grab'
                );

            }
        );


        container.on('mousemove', function(e) {

            if (!isDown) return;

            e.preventDefault();

            let x =
                e.pageX -
                container.offset().left;

            let walk =
                (x - startX) * 2;

            container.scrollLeft(
                scrollLeft - walk
            );

        });

    } catch (error) {

        console.error(error);

        frappe.msgprint(
            "Error generating table"
        );

    }
}




// =====================================
// 🔹 OPEN POPUP
// =====================================
function open_popup(
    frm,
    sample,
    test,
    input_field
) {

    frappe.call({

        method:
            "slis_app.api.Test_Result_Value.Test_Result_Value",

        args: {
            test_name: test
        },

        callback: function(r) {

            let dta = r.message;

            if (!dta) {

                frappe.msgprint(
                    "No test package found"
                );

                return;
            }

            let has_rating =
                dta.ratings &&
                dta.ratings.length > 0;



            // =====================================
            // 🔹 DIRECT INPUT
            // =====================================

            if (
                !dta.variables ||
                dta.variables.length === 0
            ) {

                frappe.prompt(

                    [{
                        label: test,
                        fieldname: "value",
                        fieldtype: "Float",
                        reqd: 1
                    }],

                    function(values) {

                        let val =
                            values.value;

                        if (has_rating) {

                            let valid = false;

                            dta.ratings.forEach(r => {

                                if (
                                    val >= r.min &&
                                    val <= r.max
                                ) {

                                    valid = true;

                                }

                            });

                            if (!valid) {

                                frappe.msgprint(
                                    "Value out of range"
                                );

                                return;
                            }
                        }

                        input_field.val(val);

                        update_json(
                            frm,
                            sample,
                            test,
                            val
                        );

                        frappe.show_alert({

                            message:
                                `${test} Saved`,

                            indicator:
                                'green'

                        });

                    },

                    "Enter Value"
                );

                return;
            }



            // =====================================
            // 🔹 FORMULA INPUT
            // =====================================

            let fields = [];

            fields.push({

                label: "Formula",

                fieldname:
                    "formula_display",

                fieldtype:
                    "Small Text",

                default:
                    dta.formula,

                read_only: 1

            });


            dta.variables.forEach(v => {

                fields.push({

                    label: v.label,

                    fieldname: v.key,

                    fieldtype: "Float",

                    default:
                        v.default || 0,

                    reqd: 1

                });

            });




            let d = new frappe.ui.Dialog({

                title: test,

                fields: fields,

                primary_action_label:
                    "Calculate",

                primary_action(values) {

                    try {

                        let formula =
                            dta.formula;

                        dta.variables.forEach(v => {

                            formula =
                                formula.replaceAll(
                                    v.key,
                                    values[v.key]
                                );

                        });

                        let result =
                            eval(formula);

                        if (has_rating) {

                            let valid = false;

                            dta.ratings.forEach(r => {

                                if (
                                    result >= r.min &&
                                    result <= r.max
                                ) {

                                    valid = true;

                                }

                            });

                            if (!valid) {

                                frappe.msgprint(
                                    "Calculated value is out of range"
                                );

                                return;
                            }
                        }

                        input_field.val(
                            result
                        );

                        update_json(
                            frm,
                            sample,
                            test,
                            result
                        );

                        d.hide();

                        frappe.show_alert({

                            message:
                                `${test} Calculated`,

                            indicator:
                                'green'

                        });

                    } catch (e) {

                        console.error(e);

                        frappe.msgprint(
                            "Formula Calculation Error"
                        );

                    }
                }
            });

            d.show();
        }
    });
}




// =====================================
// 🔹 UPDATE JSON
// =====================================
function update_json(
    frm,
    sample,
    test,
    value
) {

    let updated = false;

    (frm.doc.test_sample_data || []).forEach(row => {

        let current_sample =
            row.sample_id ||
            row.lab_code ||
            row.name;

        if (
            current_sample == sample
        ) {

            let obj = {};

            try {

                obj = JSON.parse(
                    row.values_json || "{}"
                );

            } catch (e) {

                obj = {};

            }

            obj[test] = value;

            row.values_json =
                JSON.stringify(obj);

            updated = true;

        }

    });

    if (updated) {

        frm.refresh_field(
            'test_sample_data'
        );

        frm.dirty();

    }
}

frappe.ui.form.on('Test Input Data', {

    onload(frm) {
        setTimeout(() => generate_table(frm), 200);
    },

    refresh(frm) {

        // 🔥 Save current values before rebuild
        $('.cell').each(function () {

            let sample = $(this).data('sample');
            let test   = $(this).data('test');
            let value  = $(this).val();

            if (sample && test) {
                update_json(frm, sample, test, value);
            }
        });

        bind_input_events(frm);

        setTimeout(() => generate_table(frm), 200);
    },

    tests(frm) {
        generate_table(frm);
    }
});


// =======================
// 🔹 GENERATE TABLE (FINAL)
// =======================
function generate_table(frm) {

    let data = {};

    (frm.doc.sample_data || []).forEach(row => {
        try {
            data[row.sample_id] = JSON.parse(row.values_json || "{}");
        } catch {
            data[row.sample_id] = {};
        }
    });

    // ==========================
    // 🔵 DEPARTMENT → ONLY sample_data
    // ==========================
    if (frm.doc.client_type === "Department") {

        let columns = new Set();

        Object.values(data).forEach(obj => {
            Object.keys(obj).forEach(k => columns.add(k));
        });

        let rows = Object.keys(data);

        if (rows.length === 0) {
            rows = [
                frm.doc.sample_id ||
                frm.doc.soil_sample_collection ||
                "SAMPLE"
            ];
        }

        build_table(frm, [...columns], rows);
        return;
    }

    // ==========================
    // 🟢 FARMER / CONSULTANCY → from tests
    // ==========================
    if (!frm.doc.tests || frm.doc.tests.length === 0) {

        // fallback if already saved data exists
        if (Object.keys(data).length > 0) {

            let columns = new Set();

            Object.values(data).forEach(obj => {
                Object.keys(obj).forEach(k => columns.add(k));
            });

            build_table(frm, [...columns], Object.keys(data));
            return;
        }

        frm.fields_dict.html.$wrapper.html("<p>No Tests Found</p>");
        return;
    }

    let test_list = [];

    (frm.doc.tests || []).forEach(d => {
        if (d.test_name) {
            test_list.push(String(d.test_name));
        }
    });

    frappe.call({
        method: "slis_app.api.Test_Input.get_columns",
        args: { test_list: test_list },
        callback: function(r) {

            let columns = Array.isArray(r.message) ? r.message : [];

            let sample = frm.doc.sample_id
                || frm.doc.soil_sample_collection
                || "SAMPLE";

            build_table(frm, columns, [sample]);
        }
    });
}


// =======================
// 🔹 BUILD TABLE
// =======================
function build_table(frm, final_tests, rows) {

    if (!Array.isArray(final_tests)) {
        final_tests = [final_tests];
    }

    final_tests = final_tests.map(t => String(t)).filter(t => t.length > 0);

    let data = {};

    (frm.doc.sample_data || []).forEach(row => {
        try {
            data[row.sample_id] = JSON.parse(row.values_json || "{}");
        } catch {
            data[row.sample_id] = {};
        }
    });

    let html = `
    <style>
    .table-container { width:100%; overflow-x:auto; }
    .custom-table { width:100%; min-width:max-content; }
    .custom-table th, .custom-table td { text-align:center; padding:6px; }
    .custom-table input { width:100%; min-width:80px; }
    </style>

    <div class="table-container">
    <table class="table table-bordered custom-table">
    <thead>
    <tr>
        <th style="min-width:220px;">Sample ID</th>`;

    final_tests.forEach(t => {
        html += `<th style="width:120px;">${t}</th>`;
    });

    html += `</tr></thead><tbody>`;

    rows.forEach(sample => {

        html += `<tr><td>${sample}</td>`;

        final_tests.forEach(t => {

            let value = data[sample]?.[t] || "";

            html += `
            <td>
                <input
                    value="${value}"
                    data-sample="${sample}"
                    data-test="${t}"
                    class="cell form-control"
                />
            </td>`;
        });

        html += `</tr>`;
    });

    html += `</tbody></table></div>`;

    frm.fields_dict.html.$wrapper.html(html);
}


// =======================
// 🔹 INPUT SAVE (COMMON)
// =======================
function bind_input_events(frm) {

    frm.fields_dict.html.$wrapper
        .off('input')
        .on('input', '.cell', function () {

            let sample = $(this).data('sample');
            let test   = $(this).data('test');
            let value  = $(this).val();

            update_json(frm, sample, test, value);
        });
}


// =======================
// 🔹 SAVE JSON
// =======================
function update_json(frm, sample, test, value) {

    let row = frm.doc.sample_data.find(d => d.sample_id === sample);

    if (!row) {
        row = frm.add_child('sample_data');
        row.sample_id   = sample;
        row.values_json = "{}";
    }

    let obj = {};

    try {
        obj = JSON.parse(row.values_json || "{}");
    } catch {
        obj = {};
    }

    obj[test] = value;

    row.values_json = JSON.stringify(obj);

    frm.refresh_field('sample_data');
    frm.dirty();
}

