// 🔹 CREATE NEW DOC
// =======================
function create_test_input(frm) {

    frappe.new_doc('Test Input Data', {}, (doc) => {

        // 🔹 MAIN FIELDS
        doc.soil_sample_collection = frm.doc.name;
        doc.sample_id = frm.doc.sample_id;
        doc.date_of_collection = frm.doc.date_of_collection;
        doc.number_of_samples = frm.doc.number_of_samples;
        doc.client_type = frm.doc.client_type;

        // 🔹 TESTS
        doc.tests = [];
        (frm.doc.tests || []).forEach(row => {
            doc.tests.push({ test_name: row.test_name });
        });

        // 🔹 CROPS
        doc.crops = [];
        (frm.doc.crops_list || []).forEach(row => {
            doc.crops.push({ crop_name: row.crop_name });
        });

        // 🔥 DEPARTMENT → COPY DATA
        if (frm.doc.client_type === "Department") {

            doc.sample_data = [];

            (frm.doc.sample_data || []).forEach(row => {
                doc.sample_data.push({
                    sample_id: row.sample_id,
                    values_json: row.values_json
                });
            });
        }
    });
}

