// ==========================================================
// SOIL SAMPLE COLLECTION - CLIENT SCRIPT
// ==========================================================_pr
// KEY BEHAVIOUR (as required):
// 1. Lab Code is grouped ONLY by "lab_code_prefix + Financial Year".
//    -> Changing client_type / district / panchayath / sample_id
//       will NEVER change an already generated Lab Code.
//    -> Only a change in Financial Year starts a fresh Lab Code
//       sequence.
// 2. Lab Code numbers always CONTINUE from the last number used
//    anywhere in the system for that same prefix+FY. They never
//    restart to 1 as long as prefix+FY stays same.
// 3. Clicking "Edit Table" re-draws the table but keeps the same
//    Lab Code for existing rows. Only brand-new rows (added
//    because number_of_samples increased) get new Lab Codes.
// 4. Clicking "Save Table Data" (or saving the form) stores the
//    table into the "sample_data" child table. On refresh, the
//    saved data is loaded back into the table automatically.
// ==========================================================

frappe.ui.form.on('Soil Sample Collection', {

refresh: function (frm) {

    toggle_lab_fields(frm);

    // --------------------------------------------------------
    // SAFETY RESTORE: some field-visibility configurations can
    // clear a hidden field's value on save (a known Frappe
    // behaviour when a field's depends_on evaluates to hidden
    // at save time). If Lab Code Prefix comes back EMPTY right
    // after a save/reload, but we cached a value just before
    // saving, restore it here - otherwise every subsequent
    // Edit Table click would wrongly think the prefix changed
    // and start reassigning numbers.
    // --------------------------------------------------------
    if (!frm.doc.lab_code_prefix && frm.__cached_lab_prefix) {
        frm.set_value('lab_code_prefix', frm.__cached_lab_prefix);
    }

    if (frm.fields_dict.html) {
        frm.set_df_property('html', 'hidden', 0);
    }

    // ---- Always clear old buttons first so we never get
    // ---- duplicate buttons after multiple refreshes ----
    frm.remove_custom_button('Generate Table');
    frm.remove_custom_button('Edit Table');
    frm.remove_custom_button('Generate Profile Samples');
    frm.remove_custom_button('Save Table Data');

    // =====================================
    // CLIENT TYPE
    // =====================================
    let client_type =
        (frm.doc.client_type || "")
            .toLowerCase()
            .trim();

    let allowed_clients =
        ["department", "consultancy", "farmer"];

    // =====================================
    // STEP STATUS
    // =====================================
    let has_data =
        frm.doc.sample_data &&
        frm.doc.sample_data.length > 0;

    // Existing saved data means table was already generated/saved
    frm.__table_generated =
        has_data ? true : false;

    // Check whether Profile Samples were already generated/saved
    let has_saved_profile_rows =
        has_data &&
        (frm.doc.sample_data || []).some(row =>
            /\(\d+\/\d+\)$/.test(
                (row.sample_id || "").trim()
            )
        );

    frm.__profile_generated =
        has_saved_profile_rows ? true : false;


    // =====================================
    // ONLY DEPARTMENT + CONSULTANCY + FARMER
    // =====================================
    if (allowed_clients.includes(client_type)) {

        // =====================================
        // BUTTON 1: GENERATE TABLE / EDIT TABLE
        // =====================================
        let button_label =
            has_data
                ? 'Edit Table'
                : 'Generate Table';

        frm.add_custom_button(
            button_label,
            async function () {

                // =================================
                // EDIT EXISTING TABLE
                // =================================
                if (button_label === 'Edit Table') {

                    // Keep the value user currently entered before rebuilding table.
                    // Example: DB = 3, user changed to 2.
                    frm.__edited_number_of_samples =
                        parseInt(frm.doc.number_of_samples) || 1;

                    try {

                        await render_table(frm, true);

                        frm.__table_generated = true;

                        frappe.msgprint({
                            title: __("Success"),
                            indicator: "green",
                            message: __("Table loaded successfully.")
                        });

                    } catch (error) {

                        console.error("TABLE GENERATION FAILED:", error);

                        frappe.msgprint({
                            title: __("Error"),
                            indicator: "red",
                            message: __("Unable to generate the table. Please try again.")
                        });

                        return;
                    }

                    setTimeout(() => {
                        if (cur_dialog) {
                            cur_dialog.hide();
                        }
                    }, 5000);

                    return;
                }

                // =================================
                // GENERATE TABLE
                // =================================
                if (frm.is_new()) {
                    try {
                        await frm.save();
                        await frm.reload_doc();
                    } catch (error) {
                        frappe.msgprint({
                            title: "Error",
                            indicator: "red",
                            message: "Please fill all required fields before generating the table: " + error.message
                        });
                        return;
                    }
                }

                try {

                    await render_table(frm);

                    frm.__table_generated = true;
                    frm.__profile_generated = false;

                } catch (error) {

                    console.error("TABLE GENERATION FAILED:", error);

                    frappe.msgprint({
                        title: __("Error"),
                        indicator: "red",
                        message: __("Unable to generate the table. Please try again.")
                    });

                    return;
}
                // Correct next-step notification
                if (
                    client_type === "department" &&
                    frm.doc.enable_profile_sample
                ) {

                    frappe.msgprint({
                        title: __("Success"),
                        indicator: "green",
                        message: __(
                            "Table generated successfully. Next, click Generate Profile Samples."
                        )
                    });

                    setTimeout(() => {
                        if (cur_dialog) {
                            cur_dialog.hide();
                        }
                    },5000);
                } else {

                    frappe.msgprint({
                        title: __("Success"),
                        indicator: "green",
                        message: __(
                            "Table generated successfully. Next, click Save Table Data."
                        )
                    });

                    setTimeout(() => {
                        if (cur_dialog) {
                            cur_dialog.hide();
                        }
                    }, 5000);
                                    }

                // Change Generate Table to Edit Table
                frm.remove_custom_button('Generate Table');

                frm.add_custom_button(
                    'Edit Table',
                    function () {

                        render_table(frm, true);

                        frm.__table_generated = true;
                    }
                );
            }
        );


        // =====================================
        // BUTTON 2: GENERATE PROFILE SAMPLES
        // ONLY DEPARTMENT + PROFILE ENABLED
        // =====================================
        if (
            client_type === "department" &&
            frm.doc.enable_profile_sample
        ) {

            frm.add_custom_button(
                'Generate Profile Samples',
                function () {

                    // ---------------------------------
                    // WRONG ORDER:
                    // Profile before Generate Table
                    // ---------------------------------
                    if (!frm.__table_generated) {

                        frappe.msgprint({
                            title: __("Reminder"),
                            indicator: "orange",
                            message: __("Please click Generate Table first.")
                        });
                        return;
                    }

                    // Make sure table actually exists
                    let rows =
                        frm.fields_dict.html
                            .$wrapper
                            .find("tbody tr");

                    if (!rows.length) {

                        frappe.msgprint({
                            title: __("Reminder"),
                            indicator: "orange",
                            message: __("Please click Generate Table first.")
                        });

                        return;
                    }

                    // Prevent duplicate generation
                    if (frm.__profile_generated) {

                        frappe.msgprint({
                            title: __("Reminder"),
                            indicator: "orange",
                            message: __("Profile Samples are already generated.")
                        });
                        return;
                    }

                    // =================================
                    // EXISTING PROFILE FUNCTION
                    // NO CHANGE TO FUNCTIONALITY
                    // =================================
                    generate_profile_samples(frm);

                    frm.__profile_generated = true;
                }
            );
        }


        // =====================================
        // BUTTON 3: SAVE TABLE DATA
        // =====================================
        frm.add_custom_button(
            'Save Table Data',
            async function () {

                // ---------------------------------
                // SAVE CLICKED BEFORE GENERATE TABLE
                // ---------------------------------
                if (!frm.__table_generated) {

                    frappe.msgprint({
                        title: __("Reminder"),
                        indicator: "orange",
                        message: __("Please click Generate Table first.")
                    });

                    return;
                }

                // Make sure table exists
                let rows =
                    frm.fields_dict.html
                        .$wrapper
                        .find("tbody tr");

                if (!rows.length) {

                    frappe.msgprint({
                        title: __("Reminder"),
                        indicator: "orange",
                        message: __("Please click Generate Table first.")
                    });

                    return;
                }

                // ---------------------------------
                // DEPARTMENT PROFILE:
                // PROFILE MUST BE GENERATED FIRST
                // ---------------------------------
                if (
                    client_type === "department" &&
                    frm.doc.enable_profile_sample &&
                    !frm.__profile_generated
                ) {

                    frappe.msgprint({
                        title: __("Reminder"),
                        indicator: "orange",
                        message: __("Please click Generate Profile Samples first.")
                    });

                    return;
                }

                // =================================
                // EXISTING SAVE FUNCTION
                // NO CHANGE TO FUNCTIONALITY
                // =================================
                await save_table_data(frm);
            }
        );
    }

    // =====================================
    // LOAD EXISTING TABLE (if already saved)
    // =====================================
    if (frm.doc.sample_data && frm.doc.sample_data.length > 0) {
        render_table(frm, true);
    }
},

client_type: function (frm) {
    // Simply refresh the form - refresh() handles
    // showing correct buttons for the new client_type.
    // NOTE: This does NOT touch already generated Lab Codes.
    frm.refresh();
},

status: function (frm) {

    toggle_lab_fields(frm);

    if (
        frm.fields_dict.html &&
        frm.doc.sample_data &&
        frm.doc.sample_data.length > 0
    ) {
        frm.fields_dict.html.$wrapper.empty();
        render_table(frm, true);
    }
},

lab_code_prefix: function (frm) {
    // Auto re-draw the table as soon as the Lab Code Prefix is
    // typed/changed, so the user doesn't need to remember to
    // click "Edit Table" again afterward. Existing rows are
    // still protected (see render_table's saved_data matching),
    // so this only affects brand-new rows that didn't have a
    // Lab Code yet.
    if (
        frm.fields_dict.html &&
        frm.doc.sample_data &&
        frm.doc.sample_data.length > 0
    ) {
        render_table(frm, true);
    }
}

});

// ==========================================================
// SHOW / HIDE LAB FIELDS
// ==========================================================
function toggle_lab_fields(frm) {

let show = false;

if (frm.doc.status === "With Research Assistant") {
    show = true;
}

if (frm.doc.lab_code_prefix) {
    show = true;
}

frm.set_df_property("lab_code_prefix", "hidden", !show);
frm.set_df_property("lab_code_start", "hidden", !show);

frm.refresh_field("lab_code_prefix");
frm.refresh_field("lab_code_start");

}

// ==========================================================
// FINANCIAL YEAR HELPER
// April to March cycle. e.g. Jan 2026 -> "25-26"
// ==========================================================
function get_financial_year(input_date) {

let d = new Date(input_date);

let year = d.getFullYear();
let month = d.getMonth() + 1;

let start = (month >= 4) ? year : year - 1;
let end = start + 1;

return `${String(start).slice(-2)}-${String(end).slice(-2)}`;

}

// ==========================================================
// DISTRICT SHORT CODE
