function get_district_short_code(district) {

    let district_codes = {

        "THIRUVANANTHAPURAM": "TVM",
        "KOLLAM": "KLM",
        "PATHANAMTHITTA": "PTA",
        "ALAPPUZHA": "ALP",
        "KOTTAYAM": "KTM",
        "IDUKKI": "IDK",
        "ERNAKULAM": "EKM",
        "THRISSUR": "TSR",
        "PALAKKAD": "PKD",
        "MALAPPURAM": "MPM",
        "KOZHIKODE": "KKD",
        "WAYANAD": "WYD",
        "KANNUR": "KNR",
        "KASARAGOD": "KSD"

    };

    let district_name =
        (district || "")
            .trim()
            .toUpperCase();

    return district_codes[district_name]
        || district_name;
}


// ==========================================================
// GET LAST SAMPLE NUMBER
// Used for Sample ID numbering (district/type/FY/local_body based)
// ==========================================================
// ==========================================================
// GET LAST SAMPLE NUMBER
// Optimized: directly checks Sample Data child table
// ==========================================================
// ==========================================================
// GET LAST SAMPLE NUMBER
// Server-side lookup to avoid direct Child Table query
// ==========================================================
async function get_last_number(frm, base_prefix) {

    if (!base_prefix) {
        return 0;
    }

    let r = await frappe.call({
        method:
            "slis_app.slis_app.doctype.soil_sample_collection.soil_sample_collection.get_last_sample_number",

        args: {
            base_prefix: base_prefix
        }
    });

    let max = parseInt(r.message) || 0;

    console.log(
        "LAST SAMPLE NUMBER:",
        base_prefix,
        max
    );

    return max;
}

// ==========================================================
// GET LAST LAB NUMBER
// Lab Codes are matched ONLY by "lab_code_prefix/FY" (lab_base).
// This means:
//   - client_type change        -> NO effect on lab code
//   - district/panchayath change -> NO effect on lab code
//   - sample_id change           -> NO effect on lab code
//   - Financial Year change      -> NEW lab code sequence
// It scans across ALL Soil Sample Collection records so the
// numbering always continues from wherever it left off.
// ==========================================================
// ==========================================================
// GET LAST LAB NUMBER
// Optimized: directly checks Sample Data child table
// ==========================================================
// ==========================================================
// GET LAST LAB NUMBER
// Server-side lookup to avoid direct Child Table query
// ==========================================================
async function get_last_lab_number(lab_base) {

    if (!lab_base || lab_base.startsWith("/")) {
        return 0;
    }

    let r = await frappe.call({
        method:
            "slis_app.slis_app.doctype.soil_sample_collection.soil_sample_collection.get_last_lab_number",

        args: {
            lab_base: lab_base
        }
    });

    let max = parseInt(r.message) || 0;

    console.log(
        "LAST LAB NUMBER:",
        lab_base,
        max
    );

    return max;
}
// ==========================================================
// GENERATE / RE-DRAW TABLE
// ==========================================================
async function render_table(frm, load_existing = false) {

try {

    let is_farmer =
        (frm.doc.client_type || "").toLowerCase().trim() === "farmer";

    let is_consultancy =
        (frm.doc.client_type || "").toLowerCase().trim() === "consultancy";

    let count;

    // Check whether saved data already contains generated profile children
    let has_saved_profile_rows =
        load_existing &&
        frm.doc.enable_profile_sample &&
        (frm.doc.sample_data || []).some(row =>
            /\(\d+\/\d+\)$/.test((row.sample_id || "").trim())
        );

    if (has_saved_profile_rows) {

        // After profile generation, ALL saved parent + child rows
        // must be shown in the HTML table.
        count = frm.doc.sample_data.length;

    } else if (is_farmer) {

        // FARMER:
        // Always respect the CURRENT Number of Samples field.
        //
        // Example:
        // Saved DB has 2 rows + Number of Samples changed to 3
        // -> Edit Table shows 3 rows.
        //
        // Saved DB has 3 rows + Number of Samples changed to 2
        // -> Edit Table shows 2 rows.
        //
        // If Number of Samples is empty / 0 -> default to 1 row.
        count = parseInt(frm.doc.number_of_samples) || 1;

    } else {

        count = frm.doc.number_of_samples;

        if (!count) {
            return frappe.msgprint("Enter number of samples");
        }
    }
    // =====================================
    // DEPARTMENT VALIDATION
    // =====================================
    if (!is_consultancy && !is_farmer && !frm.doc.name_of_type) {
        return frappe.msgprint("Select  Scheme or Programs");
    }
    if (is_farmer && (!frm.doc.name || frm.doc.name.startsWith("new-"))) {
        return frappe.msgprint("Please save the document once before generating the table.");
    }

    let local_body =
        frm.doc.panchayath_name || frm.doc.block_name || "";

    if (!is_consultancy && !is_farmer && !local_body) {
        return frappe.msgprint("Select Panchayath or Block");
    }

    let collection_date;

    // Farmer uses a different date field
    if (is_farmer) {

        collection_date = frm.doc.date_of_collection;

        if (!collection_date) {
            return frappe.msgprint("Please select Date Of Collection");
        }

    } else {

        collection_date = frm.doc.collection_date;

        if (!collection_date) {
            return frappe.msgprint("Please select Collection Date");
        }
    }

    // =====================================
    // LAB PREFIX
    // Lab Code generation is controlled ONLY by:
    //   - status == "With Research Assistant", OR
    //   - a Lab Code Prefix being entered
    // =====================================
    let lab_prefix = (frm.doc.lab_code_prefix || "").trim();

    // Remember the last known good prefix so we can restore it
    // if the field gets cleared unexpectedly after a save (see
    // the refresh handler's SAFETY RESTORE block above).
    if (lab_prefix) {
        frm.__cached_lab_prefix = lab_prefix;
    }

    const generate_lab_code =
        frm.doc.status === "With Research Assistant" && !!lab_prefix;

    // =====================================
    // FINAL TESTS (columns of the table)
    // =====================================
    let final_tests = [];

    if (is_farmer && (!frm.doc.tests || frm.doc.tests.length === 0)) {
        frappe.msgprint("Please add at least one test before generating the table.");
        return;
    }

    if (!is_consultancy && !is_farmer) {

        // Department: pull tests from the linked Program
        let type_doc = await frappe.db.get_doc(
            "Scheme or Programs",
            frm.doc.name_of_type
        );

        for (let t of (type_doc.test_list || [])) {

            try {

                let pkg = await frappe.db.get_doc("Soil Test Package", t.test_item);

                if (pkg.included_tests && pkg.included_tests.length > 1) {

                    pkg.included_tests.forEach(row => {
                        if (row.linked_package) {
                            final_tests.push(row.linked_package);
                        }
                    });

                } else if (pkg.included_tests && pkg.included_tests.length === 1) {

                    final_tests.push(pkg.included_tests[0].linked_package);

                } else {

                    final_tests.push(t.test_item);
                }

            } catch {
                final_tests.push(t.test_item);
            }
        }

    } else {

        // Consultancy / Farmer: pull tests from the "tests" child table
        for (let row of (frm.doc.tests || [])) {

            if (!row.test_name) continue;

            try {

                let pkg = await frappe.db.get_doc("Soil Test Package", row.test_name);

                if (pkg.included_tests && pkg.included_tests.length > 1) {

                    pkg.included_tests.forEach(r => {
                        if (r.linked_package) {
                            final_tests.push(r.linked_package);
                        }
                    });

                } else if (pkg.included_tests && pkg.included_tests.length === 1) {

                    final_tests.push(pkg.included_tests[0].linked_package);

                } else {

                    final_tests.push(row.test_name);
                }

            } catch {
                final_tests.push(row.test_name);
            }
        }
    }

    // Remove duplicate test columns
    final_tests = [...new Set(final_tests)];

    // =====================================
    // PREFIX BUILDING
    // =====================================
    // =====================================
    // PREFIX BUILDING
    // =====================================

    // Get full district name from District field
    let district =
        frm.doc.district_name || "";

    // Convert district to short code
    // Example:
    // Alappuzha -> ALP
    // Kollam -> KLM
    // Ernakulam -> EKM
    let district_short =
        get_district_short_code(district);

    let fy =
        get_financial_year(collection_date);

    // Sample ID prefix using SHORT district code
    let base_prefix =
        `${district_short}/${frm.doc.name_of_type}/${fy}/${local_body}`;

    // Lab Code base - ONLY depends on lab_prefix + FY.
    // This is what guarantees Lab Code never changes due to
    // client_type / sample_id / district changes.
    let lab_base = "";

    if (generate_lab_code) {
        lab_base = `${lab_prefix}/${fy}`;
    }

    // =====================================
    // LOAD SAVED DATA (existing rows)
    // -----------------------------------------------------
    // FIX: Keyed by ROW POSITION (1st saved row = "1", 2nd
    // saved row = "2", ...) instead of parsing a number out
    // of sample_id.
    //
    // Why this changed:
    // sample_id is BLANK for Consultancy rows, so the old
    // "parse the number from sample_id" approach could never
    // match Consultancy rows back to saved_data. That made
    // every Consultancy row look "new" on every Edit Table
    // click, so it kept getting a brand-new Lab Code instead
    // of keeping its old one.
    //
    // Row position is always available (it's just the row's
    // index in the saved child table), works identically for
    // Department, Consultancy and Farmer, and does not rely
    // on sample_id or lab_code containing a parseable number.
    // This does NOT change any Lab Code numbering/continuation
    // logic below - it only fixes how an existing row is
    // recognised as "already saved".
    // =====================================
    let saved_data = {};
    let highest_existing_number = 0;

    if (load_existing) {

        frm.doc.sample_data.forEach((row, idx) => {

            let position = idx + 1;

            if (position > highest_existing_number) {
                highest_existing_number = position;
            }

            saved_data[String(position)] = {
                sample_id: row.sample_id || "",
                lab_code: row.lab_code || "",
                values: JSON.parse(row.values_json || "{}"),
                reference_name: row.reference_name || "",
                layer: row.layer || "",
                depth: row.depth || ""
            };
        });
    }

    // =====================================
    // LAB CODE START NUMBER (fallback / manual override)
    // =====================================
    let start_no = parseInt(frm.doc.lab_code_start);

    if (isNaN(start_no) || start_no <= 0) {
        start_no = 1;
    }

    let last_lab_number = 0;

    if (generate_lab_code) {

        // Highest number already saved in database
        last_lab_number = await get_last_lab_number(lab_base);

        // Also check current document
        (frm.doc.sample_data || []).forEach(row => {

            if (!row.lab_code) return;

            if (row.lab_code.startsWith(lab_base + "/")) {

                let n = parseInt(row.lab_code.split("/").pop());

                if (!isNaN(n) && n > last_lab_number) {
                    last_lab_number = n;
                }
            }
        });
    }

    console.log("Lab Base:", lab_base);
    console.log("Last Lab Number:", last_lab_number);

    // Gentle heads-up only - does NOT block or alter any data.
    // Only shown ONCE while the prefix box stays empty (not on
    // every Edit Table click), and resets once the prefix is
    // filled back in, so it doesn't keep stacking up.
    if (load_existing && !lab_prefix && frm.doc.sample_data &&
        frm.doc.sample_data.some(r => r.lab_code)) {

        if (!frm.__lab_prefix_alert_shown) {
            frappe.show_alert({
                message: "Lab Code Prefix box is empty. Existing Lab Codes are kept as saved.",
                indicator: "orange"
            });
            frm.__lab_prefix_alert_shown = true;
        }

    } else {
        // Prefix is filled (or no lab codes exist yet) -
        // reset so the alert can show again next time it's empty.
        frm.__lab_prefix_alert_shown = false;
    }


    // =====================================
    // LAST SAMPLE NUMBER (for Sample ID, not Lab Code)
    // =====================================
    let last_number = 0;

    if (!load_existing && !is_consultancy) {

        last_number = await get_last_number(frm, base_prefix);

    } else if (load_existing) {

        last_number = highest_existing_number;
    }
    // =====================================
    // STORE PROFILE CONTEXT
    // -----------------------------------------------------
    // Layers (profile sampling) only ever applies to
    // Department samples. Consultancy and Farmer never get
    // a Layers column, even if "Enable Profile Sample" is
    // ticked - Lab Code, on the other hand, is independent
    // of client_type and applies to every type whenever
    // status is "With Research Assistant" or a Lab Code
    // Prefix is set.
    // =====================================
    let layers_applicable = !is_consultancy && !is_farmer;

    frm.__profile_context = {
        final_tests,
        show_profile: frm.doc.enable_profile_sample,
        layers_applicable,
        show_lab_code:
            frm.doc.status === "With Research Assistant" && !!frm.doc.lab_code_prefix,
        is_consultancy,
        is_farmer
    };

    // =====================================
    // BUILD TABLE HTML
    // =====================================
    let html = `
    <style>
    .table-container {
        width: 100%;
        overflow-x: auto;
        cursor: grab;
    }
    .custom-table {
        width: max-content;
        min-width: 100%;
        border-collapse: collapse;
    }
    .custom-table th,
    .custom-table td {
        text-align: center;
        padding: 6px;
        white-space: nowrap;
        border: 1px solid #ddd;
    }
    .custom-table th {
        background: #f5f5f5;
        font-weight: 600;
    }
    .custom-table input {
        width: 100%;
        min-width: 80px;
    }
    </style>

    <div class="table-container">
    <table class="table table-bordered custom-table">
    <thead>
    <tr>`;

    if (!is_consultancy && !is_farmer) {
        html += `<th style="min-width:220px;">Sample ID</th>`;
    }

    if (is_farmer) {
        html += `<th style="min-width:220px;">Sample ID</th>`;
    }

    // =====================================
    // DEPTH COLUMN
    // Department profile samples only
    // =====================================
    if (
        !is_consultancy &&
        !is_farmer &&
        has_saved_profile_rows
    ) {
        html += `
            <th style="min-width:140px;">
                Depth
            </th>
        `;
    }
    // =====================================
    // PROFILE SAMPLE - LAYERS COLUMN
    // =====================================
    const show_profile = frm.doc.enable_profile_sample;
    const layers_applicable_now = !is_consultancy && !is_farmer;

    // Show "Layers" only BEFORE profile samples are generated,
    // and only for Department samples - Consultancy and Farmer
    // never get a Layers column, even with profile sample on.
    if (show_profile && !has_saved_profile_rows && layers_applicable_now) {
        html += `<th style="min-width:100px;">Layers</th>`;
    }

    const show_lab_code =
        frm.doc.status === "With Research Assistant" && !!frm.doc.lab_code_prefix;

    html += `
    <th style="min-width:180px; ${show_lab_code ? "" : "display:none;"}">
    Lab Code
    </th>`;

    if (is_consultancy) {
        html += `<th style="min-width:180px;">Reference Name</th>`;
    }

    final_tests.forEach(t => {
        html += `<th style="width:120px;">${t}</th>`;
    });

    html += `
    </tr>
    </thead>
    <tbody>`;


    // Counts how many BRAND-NEW lab code numbers we have handed
    // out during this render. This is shared between:
    //   - truly new rows (row count increased), AND
    //   - existing rows that never got a lab code before
    //     (e.g. Lab Code Prefix was only just added now)
    // so both cases continue the SAME sequence correctly.

    // =====================================
    // BUILD EACH ROW
    // =====================================
    for (let i = 1; i <= count; i++) {

        let sample_id = "";
        let lab_code = "";
        let reference_name = "";
        let existing_values = {};
        let existing_layer = "";
        let existing_depth = "";

        let existing_row = saved_data[String(i)] || null;

        if (existing_row) {

            sample_id = existing_row.sample_id || "";

            // Split the OLD lab_code into its "base" (prefix/FY
            // part) and its trailing number, so we can check
            // whether it still belongs to the CURRENT prefix/FY.
            let existing_lab_base = "";
            let existing_lab_number = "";

            if (existing_row.lab_code) {
                let parts = existing_row.lab_code.split("/");
                existing_lab_number = parts.pop();
                existing_lab_base = parts.join("/");
            }

            if (existing_row.lab_code && !lab_prefix) {
                // -------------------------------------------------
                // SAFETY GUARD: Lab Code Prefix box is EMPTY right
                // now (user forgot to re-enter it before clicking
                // Edit Table), but this row already has a Lab Code
                // saved from before. Do NOT try to rebuild/compare
                // it using a blank prefix - that would wipe out or
                // renumber a perfectly correct saved Lab Code.
                // Just keep the old value exactly as it was saved.
                // -------------------------------------------------
                lab_code = existing_row.lab_code;

            } else if (generate_lab_code) {

                if (existing_lab_number && existing_lab_base === lab_base) {
                    // Same prefix + same FY as before -> nothing
                    // changed, so keep the EXACT same number.
                    lab_code = `${lab_base}/${existing_lab_number}`;

                } else {
                    // Either this row never had a Lab Code yet,
                    // OR the Lab Code Prefix / Financial Year was
                    // genuinely changed to a NEW value since it was
                    // last saved. Either way the old number no
                    // longer applies here, so assign a brand-new
                    // number that CONTINUES the sequence already
                    // used for the CURRENT prefix+FY (see
                    // get_last_lab_number above).
                    let new_lab_number = ++last_lab_number;

                    lab_code = `${lab_base}/${new_lab_number}`;
                }

            } else if (existing_row.lab_code) {
                // generate_lab_code is false (no prefix, status not
                // "With Research Assistant") but this row already
                // had a Lab Code saved - keep it rather than
                // blanking it out.
                lab_code = existing_row.lab_code;

            } else {
                lab_code = "";
            }

            reference_name = existing_row.reference_name || "";
            existing_values = existing_row.values || {};
            existing_layer = existing_row.layer || 1;
            existing_depth = existing_row.depth || "";

        } else {

            // --- NEW ROW: generate fresh Sample ID + Lab Code ---
            let extra = i - highest_existing_number;

            if (!is_consultancy && !is_farmer) {

                let new_sample_number = last_number + extra;
                sample_id = `${base_prefix}/${new_sample_number}`;
            }

            // Move this check BEFORE the loop, right after validation section


            if (generate_lab_code) {
                let new_lab_number = ++last_lab_number;
                lab_code = `${lab_base}/${new_lab_number}`;
            } else {
                lab_code = "";
            }
        }


        // Detect whether this SAVED row is a generated profile child
        let profile_match =
            sample_id.match(/^(.*)\s\((\d+)\/(\d+)\)$/);

        let saved_row_type = "";
        let original_sample_id = sample_id;
        let profile_sample_id = "";
        let saved_layer_no = 0;
        let saved_parent_layers = parseInt(existing_layer) || 1;

        if (has_saved_profile_rows) {

            if (profile_match) {

                saved_row_type = "child";
                original_sample_id = profile_match[1].trim();
                profile_sample_id = sample_id;
                saved_layer_no = parseInt(profile_match[2]) || 0;
                saved_parent_layers = parseInt(profile_match[3]) || 1;

            } else {

                saved_row_type = "parent";
                original_sample_id = sample_id;
                saved_parent_layers = parseInt(existing_layer) || 1;
            }
        }

        html += `
        <tr
            ${has_saved_profile_rows ? `
                class="${saved_row_type === "parent"
                    ? "profile-parent-row"
                    : "profile-child-row"}"
                data-row-type="${saved_row_type}"
                data-sample-id="${original_sample_id}"
                data-profile-sample-id="${profile_sample_id}"
                data-layer-no="${saved_layer_no}"
                data-parent-layers="${saved_parent_layers}"
            ` : ""}
        >`;

        if (!is_consultancy) {
            html += `<td>${sample_id}</td>`;
        }

        // =====================================
        // DEPTH VALUE
        // Department profile samples only
        // =====================================
        if (
            !is_consultancy &&
            !is_farmer &&
            has_saved_profile_rows
        ) {
            html += `
                <td>
                    ${
                        saved_row_type === "child"
                            ? (existing_depth || "-")
                            : "-"
                    }
                </td>
            `;
        }
        // Layers input is required only before profile generation,
        // and only for Department samples (see layers_applicable_now).
        // Saved generated profile rows already contain:
        // Parent
        // Parent (1/4)
        // Parent (2/4)
        // etc.
        if (show_profile && !has_saved_profile_rows && layers_applicable_now) {

            html += `
            <td>
                <input
                    type="number"
                    min="1"
                    value="${existing_layer}"
                    class="layer-input form-control"
                    placeholder="Layers">
            </td>`;
        }

        html += `
        <td style="${show_lab_code ? "" : "display:none;"}">
            ${lab_code}
        </td>`;

        if (is_consultancy) {
            html += `
            <td>
                <input
                    type="text"
                    value="${reference_name}"
                    data-lab="${lab_code}"
                    class="reference-name-input form-control">
            </td>`;
        }

        final_tests.forEach(t => {

            let value = existing_values[t] || "";

            html += `
            <td>
                <input
                    type="text"
                    value="${value}"
                    data-sample="${sample_id}"
                    data-lab="${lab_code}"
                    data-test="${t}"
                    class="test-input form-control"
                    ${has_saved_profile_rows && saved_row_type === "parent"
                        ? "readonly"
                        : ""}>
            </td>`;
        });

        html += `</tr>`;
    }

    html += `
    </tbody>
    </table>
    </div>`;

    frm.fields_dict.html.$wrapper.html(html);

    console.log("TABLE GENERATED");
    console.log(html);

    // =====================================
    // DRAG-TO-SCROLL FOR WIDE TABLES
    // =====================================
    let container = frm.fields_dict.html.$wrapper.find('.table-container');

    let isDown = false;
    let startX;
    let scrollLeft;

    container.off('mousedown mouseleave mouseup mousemove');

    container.on('mousedown', function (e) {
        isDown = true;
        startX = e.pageX - container.offset().left;
        scrollLeft = container.scrollLeft();
    });

    container.on('mouseleave mouseup', function () {
        isDown = false;
    });

    container.on('mousemove', function (e) {
        if (!isDown) return;
        e.preventDefault();
        let x = e.pageX - container.offset().left;
        let walk = (x - startX) * 2;
        container.scrollLeft(scrollLeft - walk);
    });

} catch (error) {

    console.error("render_table error:", error);
    console.error("Error type:", typeof error);
    console.error("Full error:", error);

    throw error;
}
}

// ==========================================================
// GENERATE PROFILE SAMPLES
// STEP 1 - READ ALL TABLE DATA
// ==========================================================
function generate_profile_samples(frm) {

const ctx = frm.__profile_context;

let profile_rows = [];

let rows = frm.fields_dict.html.$wrapper.find("tbody tr");

rows.each(function () {

    let row = $(this);

    let row_data = {
        sample_id: "",
        lab_code: "",
        depth: "",
        reference_name: "",
        layers: 1,
        values: {}
    };

    // -------------------------
    // DEPTH
    // -------------------------
    if (ctx.show_profile && ctx.layers_applicable) {
        row_data.depth = row.find(".depth-input").val() || "";
    }

    // -------------------------
    // SAMPLE ID
    // -------------------------
    if (!ctx.is_consultancy) {
        row_data.sample_id = row.find("td").eq(0).text().trim();
    }

    // -------------------------
    // LAYERS
    // -------------------------
    // Layers only ever applies to Department samples - Consultancy
    // and Farmer never render a Layers column, even with profile
    // sample enabled, so only read it here for Department rows.
    if (ctx.show_profile && ctx.layers_applicable) {
        row_data.layers = parseInt(
            row.find(".layer-input").val() || 1
        );
    }

    // -------------------------
    // LAB CODE
    // -------------------------
    // The Lab Code column index depends on BOTH whether a Sample ID
    // column is present (absent only for Consultancy) AND whether a
    // Layers column is present (present only for Department rows
    // when profile sample is enabled - never for Consultancy/Farmer).
    let lab_index =
        (ctx.is_consultancy ? 0 : 1) +
        ((ctx.show_profile && ctx.layers_applicable) ? 1 : 0);

    row_data.lab_code =
        row.find("td").eq(lab_index).text().trim();

    // -------------------------
    // REFERENCE NAME
    // -------------------------
    if (ctx.is_consultancy) {
        row_data.reference_name =
            row.find(".reference-name-input").val() || "";
    }

    // -------------------------
    // TEST VALUES
    // -------------------------
    row.find(".test-input").each(function () {

        let input = $(this);

        row_data.values[input.data("test")] = input.val();

    });

    profile_rows.push(row_data);

    // Store data for next step
    frm.__profile_rows = profile_rows;

});

console.clear();

console.log("PROFILE DATA");

console.table(profile_rows);

console.log("Stored Profile Rows");
console.log(frm.__profile_rows);
// ======================================
// BUILD PARENT + CHILD DATA
// ======================================
let expanded_rows = [];

frm.__profile_rows.forEach(parent => {

    // Parent row
    expanded_rows.push({
        ...parent,
        row_type: "parent",
        layer_no: 0
    });

    // Child rows
    for (let i = 1; i <= parent.layers; i++) {

        expanded_rows.push({
            // Original parent sample ID
            sample_id: parent.sample_id,

            // Actual generated profile sample ID
            profile_sample_id:
                `${parent.sample_id} (${i}/${parent.layers})`,

            lab_code: parent.lab_code,
            reference_name: parent.reference_name,

            depth: parent.depth || "",

            layers: 1,
            parent_layers: parent.layers,

            values: { ...parent.values },

            row_type: "child",
            layer_no: i
        });

    }

});

console.log("EXPANDED ROWS");
console.table(expanded_rows);

frm.__expanded_rows = expanded_rows;

// Show generated profile table
render_profile_table(frm);

frappe.msgprint({
    title: __("Success"),
    indicator: "green",
    message: __(
        "Profile Samples generated successfully. Next, click Save Table Data."
    )
});

setTimeout(() => {
    if (cur_dialog) {
        cur_dialog.hide();
    }
}, 5000);
}

// ==========================================================
// RENDER PROFILE SAMPLE TABLE
// ==========================================================
function render_profile_table(frm) {

const ctx = frm.__profile_context;
const expanded_rows = frm.__expanded_rows || [];

if (!ctx || !expanded_rows.length) {
    frappe.msgprint("No profile sample data found.");
    return;
}

const final_tests = ctx.final_tests || [];
const show_lab_code = ctx.show_lab_code;
const is_consultancy = ctx.is_consultancy;

let html = `
<style>
    .table-container {
        width: 100%;
        overflow-x: auto;
    }

    .custom-table {
        width: max-content;
        min-width: 100%;
        border-collapse: collapse;
    }

    .custom-table th,
    .custom-table td {
        text-align: center;
        padding: 6px;
        white-space: nowrap;
        border: 1px solid #ddd;
    }

    .custom-table th {
        background: #f5f5f5;
        font-weight: 600;
    }

    .custom-table input {
        width: 100%;
        min-width: 80px;
    }

    .profile-parent-row {
        background: #f8f9fa;
        font-weight: 600;
    }
</style>

<div class="table-container">

<table class="table table-bordered custom-table">

<thead>
<tr>
`;

// Sample ID
if (!is_consultancy) {
    html += `
        <th style="min-width:300px;">
            Sample ID
        </th>
    `;
}

// DEPTH
if (!is_consultancy) {
    html += `
        <th style="min-width:140px;">
            Depth
        </th>
    `;
}

// Lab Code
html += `
    <th style="
        min-width:180px;
        ${show_lab_code ? "" : "display:none;"}
    ">
        Lab Code
    </th>
`;

// Consultancy Reference Name
if (is_consultancy) {

    html += `
        <th style="min-width:180px;">
            Reference Name
        </th>
    `;
}

// TEST HEADERS
final_tests.forEach(test => {

    html += `
        <th style="min-width:120px;">
            ${test}
        </th>
    `;
});

html += `
    </tr>
    </thead>

    <tbody>
`;

// ==========================================
// BUILD PARENT + PROFILE CHILD ROWS
// ==========================================

expanded_rows.forEach(row => {

    let is_parent = row.row_type === "parent";

    // Sample ID display
    let sample_display = row.sample_id;

    if (!is_parent) {
        sample_display = row.profile_sample_id;
    }

    html += `
        <tr
            class="${is_parent ? "profile-parent-row" : "profile-child-row"}"
            data-row-type="${row.row_type}"
            data-sample-id="${row.sample_id}"
            data-profile-sample-id="${row.profile_sample_id || ""}"
            data-layer-no="${row.layer_no || 0}"
            data-parent-layers="${row.parent_layers || row.layers || 1}"
        >
    `;

    // SAMPLE ID
    if (!is_consultancy) {

        html += `
            <td>
                ${sample_display}
            </td>
        `;
    }

    // DEPTH
if (!is_consultancy && !is_parent) {

    html += `
        <td>
            <input
                type="text"
                value="${row.depth || ""}"
                class="depth-input form-control"
                placeholder="Enter Depth"
            >
        </td>
    `;
}

    // LAB CODE
    html += `
        <td style="${show_lab_code ? "" : "display:none;"}">
            ${row.lab_code || ""}
        </td>
    `;

    // REFERENCE NAME
    if (is_consultancy) {

        html += `
            <td>
                <input
                    type="text"
                    value="${row.reference_name || ""}"
                    class="reference-name-input form-control"
                    ${is_parent ? "readonly" : ""}
                >
            </td>
        `;
    }

    // TEST VALUES
    final_tests.forEach(test => {

        let value =
            row.values && row.values[test] !== undefined
                ? row.values[test]
                : "";

        html += `
            <td>
                <input
                    type="text"
                    value="${value}"
                    data-test="${test}"
                    data-sample="${row.sample_id}"
                    data-layer="${is_parent ? "" : `${row.layer_no}/${row.parent_layers}`}"
                    class="test-input form-control"
                    ${is_parent ? "readonly" : ""}
                >
            </td>
        `;
    });

    html += `</tr>`;
});

html += `
    </tbody>
    </table>
    </div>
`;

frm.fields_dict.html.$wrapper.html(html);

console.log("PROFILE TABLE RENDERED");
console.log(expanded_rows);

}

async function save_table_data(frm) {

// ==========================================================
// SAVE TABLE DATA
// Reads values straight from the HTML table and writes them
// into the "sample_data" child table, then saves the document.
// On the next refresh, these values are read back and shown
// again in the table (see render_table's load_existing branch).
// ==========================================================

try {

    // =====================================
    // KEEP CURRENT NUMBER OF SAMPLES
    // =====================================
    // Example:
    // DB currently has 3
    // User changes it to 2
    // Edit Table shows 2 rows
    // Save Table Data must save 2, not restore 3
    // Set this at START of render_table, regardless of whether it's edit or generate
    // At the START of render_table(), after count is calculated:

    // Cache the current prefix right before saving, in case the
    // save/reload cycle clears the field's value afterward.
    let current_prefix = (frm.doc.lab_code_prefix || "").trim();
    if (current_prefix) {
        frm.__cached_lab_prefix = current_prefix;
    }
        let current_number_of_samples = parseInt(frm.doc.number_of_samples) || 1;


    frm.clear_table("sample_data");

    let rows = frm.fields_dict.html.$wrapper.find("tbody tr");

    rows.each(function () {

        let row = $(this);

        // =====================================
        // PROFILE ROW INFORMATION
        // =====================================
        let row_type = row.attr("data-row-type") || "";
        let original_sample_id = row.attr("data-sample-id") || "";
        let profile_sample_id = row.attr("data-profile-sample-id") || "";

        let layer_no =
            parseInt(row.attr("data-layer-no") || 0);

        let parent_layers =
            parseInt(row.attr("data-parent-layers") || 0);

        let is_profile_parent =
            row_type === "parent";

        let is_profile_child =
            row_type === "child";

        // =====================================
        // EXISTING CODE CONTINUES
        // =====================================
        let is_consultancy =
            (frm.doc.client_type || "").toLowerCase().trim() === "consultancy";

        let is_farmer =
            (frm.doc.client_type || "").toLowerCase().trim() === "farmer";

        let sample_id = "";

        if (!is_consultancy) {

            // Profile child:
            // Save generated ID like:
            // SampleID (1/4), SampleID (2/4), etc.
            if (is_profile_child && profile_sample_id) {

                sample_id = profile_sample_id;

            }
            // Profile parent:
            // Save original Sample ID
            else if (is_profile_parent && original_sample_id) {

                sample_id = original_sample_id;

            }
            // Normal non-profile table
            else {

                sample_id = row.find("td").eq(0).text().trim();
            }
        }

        let lab_code = "";

        // Generated profile table
        if (is_profile_parent || is_profile_child) {

            // Profile table (Layers column no longer present here):
            // Department/Farmer = Sample ID, Lab Code
            // Consultancy = Lab Code, Reference Name
            let lab_index = is_consultancy ? 0 : 1;

            lab_code = row.find("td").eq(lab_index).text().trim();

        } else {

            // Normal table BEFORE profile generation.
            // Lab Code column index depends on whether a Sample ID
            // column exists (absent only for Consultancy) AND
            // whether a Layers column exists. Layers only ever
            // applies to Department rows - it's never shown for
            // Consultancy or Farmer, even with Profile Sample on -
            // so Consultancy always stays at index 0 and Farmer
            // always stays at index 1 here, regardless of the
            // enable_profile_sample setting.
            let layers_applicable = !is_consultancy && !is_farmer;

            let lab_index =
                (is_consultancy ? 0 : 1) +
                ((frm.doc.enable_profile_sample && layers_applicable) ? 1 : 0);

            lab_code = row.find("td").eq(lab_index).text().trim();
        }

        let reference_name = "";

        if (is_consultancy) {
            reference_name =
                row.find(".reference-name-input").val() || "";
        }

        let values_json = {};

        row.find(".test-input").each(function () {

            let input = $(this);

            let test = input.data("test");
            let value = input.val();

            values_json[test] = value;
        });


        let depth = "";



        if (
            !is_consultancy &&
            !is_farmer &&
            is_profile_child
        ) {
            depth = row.find(".depth-input").val() || "";
        }


        let child = frm.add_child("sample_data");

        child.sample_id = sample_id;
        child.lab_code = lab_code;
        child.depth = depth;
        child.reference_name = reference_name;
        child.values_json = JSON.stringify(values_json);

        // =====================================
        // SAVE PROFILE LAYER INFORMATION
        // =====================================
        if (is_profile_child) {

            // Example: 1/4, 2/4, 3/4, 4/4
            child.layer = `${layer_no}/${parent_layers}`;

        } else if (is_profile_parent) {

            // Parent stores total number of layers
            child.layer = parent_layers;

        } else if (frm.doc.enable_profile_sample && !is_consultancy && !is_farmer) {

            // Before Generate Profile Samples:
            // save the Layers input value (Department only -
            // Consultancy/Farmer never render a layer-input)
            child.layer =
                row.find(".layer-input").val() || 1;
        }
    });

    frm.refresh_field("sample_data");

    // =====================================
    // KEEP NEW NUMBER OF SAMPLES ON SAVE
    // =====================================
    // Preserve the value currently entered by the user.
    await frm.set_value(
        "number_of_samples",
        current_number_of_samples
    );

    frm.refresh_field("number_of_samples");

    await frm.save();
    frappe.msgprint({
        title: __("Success"),
        indicator: "green",
        message: __("Table Data Saved successfully.")
    });

    setTimeout(() => {
        if (cur_dialog) {
            cur_dialog.hide();
        }
    }, 5000);

    } catch (e) {
        console.error(e);
        frappe.msgprint("Error Saving Table Data");
    }

    }

