frappe.ui.form.on('Soil Sample Collection', {
    refresh(frm) {

        // Hide Help button
        frm.page.wrapper.find('button').filter(function() {
            return $(this).text().trim() === 'Help';
        }).hide();

        // Hide Actions dropdown
        setTimeout(() => {
            $('.actions-btn-group').hide();
        }, 300);

        if (!frm.doc.workflow_state || frm.is_new()) return;

        // Get ONLY workflow transitions for current state and user
        frappe.call({
            method: 'frappe.model.workflow.get_transitions',
            args: { doc: frm.doc },
            callback: function(r) {
                if (!r.message || !r.message.length) return;

                // Remove old custom buttons
                frm.page.inner_toolbar.find('.custom-action-btn').remove();

                // Add one button per workflow transition
                r.message.forEach(transition => {
                    frm.add_custom_button(__(transition.action), function() {

                        frappe.confirm(
                            `Are you sure you want to perform "${transition.action}"?`,
                            () => {
                                frappe.call({
                                    method  : 'frappe.model.workflow.apply_workflow',
                                    args    : {
                                        doc   : frm.doc,
                                        action: transition.action
                                    },
                                    freeze  : true,
                                    freeze_message: `Applying ${transition.action}...`,
                                    callback: function(r) {
                                        if (r.message) {
                                            frm.doc = r.message;
                                            frm.refresh();
                                            frappe.show_alert({
                                                message  : `✅ ${transition.action} done!`,
                                                indicator: 'green'
                                            }, 3);
                                        }
                                    }
                                });
                            }
                        );

                    }).addClass('custom-action-btn btn-primary');
                });

                console.log("✅ Workflow transitions →", r.message.map(t => t.action));
            }
        });
    }
});

