frappe.ui.form.on('User', {
    refresh(frm) {
        if (!frm.is_new()) {
            // 1. Button directly visible (no group), placed outside any group
            frm.add_custom_button(__('Create Employee'), function() {

                // 2. Check if Employee already exists for this User
                frappe.db.get_value('Employee', { user_id: frm.doc.name }, 'name')
                    .then(r => {
                        if (r.message && r.message.name) {
                            frappe.msgprint({
                                title: __('Employee Already Exists'),
                                message: __('An Employee record already exists for this user: <b>{0}</b>', [r.message.name]),
                                indicator: 'orange'
                            });
                        } else {
                            frappe.new_doc('Employee', {
                                user_id: frm.doc.name,
                                employee_name: frm.doc.full_name,
                                company_email: frm.doc.email,
                                first_name: frm.doc.first_name,
                                middle: frm.doc.middle,
                                last_name: frm.doc.last_name,
                            });
                        }
                    });

            }); // <-- No third argument = button appears directly, not inside a group
        }
    },

    // 3. Validate unique username before save
    username(frm) {
        if (frm.doc.username) {
            frappe.db.get_value('User', { username: frm.doc.username, name: ['!=', frm.doc.name] }, 'name')
                .then(r => {
                    if (r.message && r.message.name) {
                        frappe.msgprint({
                            title: __('Duplicate Username'),
                            message: __('The username <b>{0}</b> is already taken. Please choose a different one.', [frm.doc.username]),
                            indicator: 'red'
                        });
                        frm.set_value('username', '');
                    }
                });
        }
    },

    validate(frm) {
        if (frm.doc.username) {
            return frappe.db.get_value('User', { username: frm.doc.username, name: ['!=', frm.doc.name] }, 'name')
                .then(r => {
                    if (r.message && r.message.name) {
                        frappe.throw(__('Username <b>{0}</b> is already in use. Please choose a unique username.', [frm.doc.username]));
                    }
                });
        }
    }
});

