frappe.ui.form.on("Soil Sample Collection", {
    before_workflow_action(frm) {
        if (frm.doc.status === "With Research Assistant") {
            let file_no = (frm.doc.file_number || "").trim();

            if (!file_no && !frm._file_no_confirmed) {
                let action = frm.selected_workflow_action;
                frappe.dom.unfreeze();

                let d = new frappe.ui.Dialog({
                    title: __("Reminder"),
                    fields: [
                        {
                            fieldtype: "HTML",
                            options: `<p>${__("File Number is not filled. Do you want to proceed anyway?")}</p>`
                        }
                    ],
                    primary_action_label: __("OK"),
                    primary_action: function() {
                        d.hide();
                        frm._file_no_confirmed = true;
                        frappe.dom.freeze();
                        frappe.xcall("frappe.model.workflow.apply_workflow", {
                            doc: frm.doc,
                            action: action
                        }).then((doc) => {
                            frappe.dom.unfreeze();
                            frm._file_no_confirmed = false;
                            frappe.model.sync(doc);
                            frm.refresh();
                        }).catch((err) => {
                            frappe.dom.unfreeze();
                            frm._file_no_confirmed = false;
                            console.error("Workflow action failed:", err);
                        });
                    }
                });

                d.show();
                frappe.throw();
            }
        }
    }
});

